import { useEffect, useState } from 'react';

import { MouseCoordinate } from '../types/overlays.js';

/**
 * Hook responsible to set and return the closest point
 *
 * @param mousePosition - mouse position
 * @param width - width
 * @param height - height
 * @param closestPointHandler -closest point handler
 */
export function useClosestPoint<T>(
  mousePosition: MouseCoordinate | undefined,
  width: number,
  height: number,
  closestPointHandler: (m: MouseCoordinate) => T | undefined,
) {
  const [closestPoint, setClosestPoint] = useState<T>();

  useEffect(() => {
    if (!mousePosition) {
      return;
    }
    const closestPoint = closestPointHandler(mousePosition);
    setClosestPoint(closestPoint);
  }, [mousePosition, width, height]);

  return closestPoint;
}
